    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 200;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 200;
    private static final int LONG_SIMULATION_STEPS = 4000;
    private static final int SIMULATION_DELAY_MS = 5;

    // List of organisms in the field.
    private List<Organism> organisms;
    // The current state of the field.
    private Field field;
    // A graphical view of the simulation.
    private SimulatorView view;
    // The current simulation clock.
    private SimulationClock clock;

    // The current weather in the simulation.
    private Weather currentWeather;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        organisms = new ArrayList<>();
        field = new Field(depth, width);
        clock = new SimulationClock();

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);

        // Setup a valid starting point
        reset();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        simulate(LONG_SIMULATION_STEPS);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            simulateOneStep();
            delay(SIMULATION_DELAY_MS);
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * organism.
     */
    public void simulateOneStep()
    {
        clock.advanceStep();

        // Provide space for newborn organisms.
        List<Organism> newOrganisms = new ArrayList<>();
        // Let all organisms act.
        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
            Organism organism = it.next();

            organism.act(newOrganisms, currentWeather, clock.getCurrentTime());

            if(organism.isRemoved()) {
                it.remove();
            }
        }

        // Add the newly born organisms to the main list.
        organisms.addAll(newOrganisms);

        view.showStatus(clock.getStep(), field);
        view.updateTimeLabel(clock.getDay(), clock.getHour());
        view.updateEnvironmentLabel(currentWeather, clock.getCurrentTime());

        // Every hour, generate new weather if we are done with current weather.
        if (clock.isStartOfHour()) {
            currentWeather.generate();
        }

        // Update time of day at the configured interval.
        clock.advanceTimeOfDayIfNeeded();
    }

    public int getHour() {
        return clock.getHour();
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        clock.reset();
        currentWeather = new Weather(WeatherType.SUN);

        organisms.clear();

        Populator populator = new Populator(view);
        populator.populate(organisms, field);

        // Show the starting state in the view.
        view.showStatus(clock.getStep(), field);
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }
}
/**
 * Tracks simulation step, hour, day, and time-of-day progression.
 */
public class SimulationClock {

    private static final int STEPS_PER_HOUR = 5;
    private static final int HOURS_PER_DAY = 24;
    private static final int STEPS_PER_DAY = STEPS_PER_HOUR * HOURS_PER_DAY;
    private static final int HOURS_PER_TIME_OF_DAY = 4;

    private int step;
    private int hour;
    private TimeOfDay currentTime;

    /**
     * Constructor for a simulation clock.
     */
    public SimulationClock() {
        reset();
    }

    /**
     * Reset the clock to the initial simulation time.
     */
    public void reset() {
        step = 0;
        hour = 0;
        currentTime = TimeOfDay.SUNRISE;
    }

    /**
     * Advance the simulation by one step.
     */
    public void advanceStep() {
        step++;
        hour = (step / STEPS_PER_HOUR) % HOURS_PER_DAY + 1;
    }

    /**
     * Advance time of day when the current step reaches a transition boundary.
     */
    public void advanceTimeOfDayIfNeeded() {
        if ((hour % HOURS_PER_TIME_OF_DAY == 0) && isStartOfHour()) {
            currentTime = currentTime.next();
        }
    }

    /**
     * Whether this step begins a new simulated hour.
     *
     * @return true if the step begins a new simulated hour.
     */
    public boolean isStartOfHour() {
        return step % STEPS_PER_HOUR == 0;
    }

    /**
     * Return the current simulation step.
     *
     * @return The current step.
     */
    public int getStep() {
        return step;
    }

    /**
     * Return the current simulation day.
     *
     * @return The current day.
     */
    public int getDay() {
        return step / STEPS_PER_DAY + 1;
    }

    /**
     * Return the current simulation hour.
     *
     * @return The current hour.
     */
    public int getHour() {
        return hour;
    }

    /**
     * Return the current time of day.
     *
     * @return The current time of day.
     */
    public TimeOfDay getCurrentTime() {
        return currentTime;
    }
}
